import { LightningElement } from 'lwc';
export default class LwcNoteCreateModal extends LightningElement {
    handleSelected (event) {
      const selected = new CustomEvent('selected', {
        bubbles: true,
        composed: true,
        detail: event.detail
      });
    this.dispatchEvent(selected);
  }
}

